// Expo config plugin: keep every CocoaPods target at or above the app's minimum iOS.
//
// ios/ is generated by `expo prebuild`, so a hand edit to the Podfile is lost on
// the next regenerate. This patches the generated Podfile's post_install instead.
//
// Why: new Xcode releases only accept deployment targets 15.0+, and some pods
// (and their resource-bundle targets: RNSVG-RNSVGFilters, ReachabilitySwift,
// Sentry) still declare 11.0 / 12.x, which fails the build with
// "The iOS deployment target ... is set to X, but the range of supported
// deployment target versions is 15.0 to ...".
const { withDangerousMod } = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

const MARKER = '# [withPodDeploymentTarget]';

const SNIPPET = `
    ${MARKER} raise pod targets below the app minimum to it.
    min_ios = Gem::Version.new(podfile_properties['ios.deploymentTarget'] || '15.1')
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |config|
        current = config.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        if current.nil? || Gem::Version.new(current.to_s) < min_ios
          config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = min_ios.to_s
        end
      end
    end
`;

function patchPodfile(source) {
  if (source.includes(MARKER)) return source; // already patched
  // Insert right after the react_native_post_install(...) call.
  const patched = source.replace(/(react_native_post_install\([\s\S]*?\n\s*\)\n)/, `$1${SNIPPET}`);
  return patched;
}

module.exports = function withPodDeploymentTarget(config) {
  return withDangerousMod(config, [
    'ios',
    async (cfg) => {
      const file = path.join(cfg.modRequest.platformProjectRoot, 'Podfile');
      if (!fs.existsSync(file)) return cfg;
      const before = fs.readFileSync(file, 'utf8');
      const after = patchPodfile(before);
      if (after !== before) fs.writeFileSync(file, after);
      return cfg;
    },
  ]);
};
module.exports.patchPodfile = patchPodfile;
